def img(name,alt,cls='',eager=False):return f'<img class="{cls}" src="/images/{name}" alt="{E(alt)}" width="1200" height="800" '+('fetchpriority="high"' if eager else 'loading="lazy"')+'>'
def button(text,href=BOOK,secondary=False):return f'<a class="mp-button{" mp-outline" if secondary else ""}" href="{href}">{text} <span aria-hidden="true">↗</span></a>'
def eyebrow(text):return f'<p class="mp-eyebrow">{text}</p>'
def closing(title,body,primary='Book your next shoot',href=BOOK):return f'<section class="mp-close"><div class="mp-wrap"><div>{eyebrow("ListerPros · Arizona since 2013")}<h2>{title}</h2><p>{body}</p></div><div class="mp-actions">{button(primary,href)}{button("Talk to our team","tel:4805827767",True)}</div></div></section>'
