def pricing(source):
 cards=source.select('.pricing-card');names=['Photos Only','Essential','Premier','Elite'];goals=['A polished MLS debut','Photos + a sense of the layout','Video + your personal brand','The complete presentation'];descriptions=['Keep it focused on professional listing photos.','Add a Zillow 3D tour and floor plan to your photos.','Bring the home and your on-camera presence together.','Combine photography, video, drone and Matterport.']
 rendered=[]
 for i,c in enumerate(cards):
  data=' '.join(f'{k}="{E(str(v),quote=True)}"' for k,v in c.attrs.items() if k.startswith('data-'))
  items=[]
  for li in c.select('li'):
   text=li.get_text(' ',strip=True)
   if '20-35' in text:text=E(text).replace('20-35','<span class="photos-display">20–35</span>')
   else:text=E(text)
   items.append('<li>'+text+'</li>')
  rendered.append(f'<article class="mp-package pricing-card" data-package="{i}" {data}><p class="mp-package-goal">{goals[i]}</p><h3>{names[i]}</h3><p class="mp-package-description">{descriptions[i]}</p><p class="mp-package-price"><strong class="price-display">${c["data-price-small"]}</strong><span>/ shoot</span></p><p class="sqft-display">Up to 2,000 sq ft</p><ul>{"".join(items)}</ul>{button("Choose "+names[i])}</article>')
 addon=next(h for h in source.find_all('h2') if 'Carte' in h.text).find_parent('section');groups=[]
 for h in addon.select('h3'):
  box=h.find_parent('div').parent;rows=[]
  for li in box.select('li'):
   spans=li.find_all('span',recursive=False)
   if len(spans)==2:
    label=spans[0].get_text(' ',strip=True);price=spans[1].get_text(' ',strip=True)
